def get_min_dist(x, K):
    possible_sums = {0}
    for val in x:
        new_sums = set()
        for s in possible_sums:
            if s + val <= K + 100:
                new_sums.add(s + val)
        possible_sums.update(new_sums)

    min_dist = float('inf')
    for s in possible_sums:
        min_dist = min(min_dist, abs(s - K))
    return min_dist

def solve():
    K = 1810
    max_d = 0
    # Test constant x_i
    for a in range(90, 101):
        n = (K + a - 1) // a
        if n < 19: continue
        x = [a] * n
        max_d = max(max_d, get_min_dist(x, K))
    print(f"Max d for constant x_i (a>=90): {max_d}")

solve()
